1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create-owner request whose firstName, lastName, address, city or telephone is
13	 * missing or blank, before {@link BuildOwner} runs. Publishes the body for later steps.
14	 */
15	public class RequireOwnerFields {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
18	            throws MissingOwnerFieldsException {
19	        List<String> missing = new ArrayList<>();
20	        addIfBlank(missing, "firstName", request.getFirstName());
21	        addIfBlank(missing, "lastName", request.getLastName());
22	        addIfBlank(missing, "address", request.getAddress());
23	        addIfBlank(missing, "city", request.getCity());
24	        addIfBlank(missing, "telephone", request.getTelephone());
25	        if (!missing.isEmpty()) {
26	            throw new MissingOwnerFieldsException(missing);
27	        }
28	        // Normalise the telephone to its digits and require exactly 10 of them.
29	        String telephone = request.getTelephone().replaceAll("\\D", "");
30	        if (telephone.length() != 10) {
31	            throw new MissingOwnerFieldsException(List.of("telephone"));
32	        }
33	        request.setTelephone(telephone);
34	        validated.set(request);
35	    }
36	
37	    private static void addIfBlank(List<String> missing, String name, String value) {
38	        if (value == null || value.isBlank()) {
39	            missing.add(name);
40	        }
41	    }
42	}
